"""Register WebGL-validated jump assets and write publishing copy for the completed film."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
slug='every-human-jumped-at-once'
def read(p):return json.loads((ROOT/p).read_text(encoding='utf-8'))
def write(p,v):(ROOT/p).write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
story=read(f'stories/{slug}.json')
registry=read('assets/registry.json')
present={a['id'] for a in registry['assets']}
for candidate in story['asset_plan']['new_reusable_asset_candidates']:
    path=ROOT/candidate['suggested_path']
    if not path.is_file() or path.stat().st_size<100:raise RuntimeError(f'Asset missing: {path}')
    if candidate['proposed_id'] in present:continue
    registry['assets'].append(dict(id=candidate['proposed_id'],name=candidate['proposed_id'].replace('-v1','').replace('-',' ').title(),type='three_component',source_path=candidate['suggested_path'],description=candidate['description'],tags={'synchronized-jump-motion-v1':['human','jump','ballistic','motion','physics'],'center-of-mass-recoil-diagram-v1':['momentum','recoil','center-of-mass','schematic'],'crowd-field-v1':['crowd','people','instanced','aerial','city'],'water-service-station-v1':['water','infrastructure','tank','plumbing']}[candidate['proposed_id']],configurable_parameters=candidate['parameters'],created_for=slug,used_in=[],license='original_procedural',notes='Original parameterised Three.js code validated in Chrome WebGL storyboard frame captures. All motion is evaluated from caller time. Crowd silhouettes are for mid-distance/aerial use. Recoil display displacement is independently exaggerated and requires a schematic label; mass ratio is used only for the physical displacement calculation.'))
write('assets/registry.json',registry)
scope='Illustrative 8.2 billion population (UN 2024 baseline), assumed mean mass 62 kg, ideal simultaneous 0.30 m center-of-mass jump. The isolated Earth-human center of mass gets no orbital boost. Peak Earth recoil ~2.55e-14 m is larger than a proton but ~4000 times smaller than a representative 1e-10 m atom. Total landing energy ~1.5e12 J does not imply a single earthquake magnitude or acoustic level; coupling and coherence are unknown. The 1640 km2 estimate assumes a dangerous 5 people/m2 and excludes roads, services and safe jumping space. Representative blocks, synthetic seismic trace and radial arrows are explanatory; real population distribution is uneven.'
sources='Sources and assumptions: NASA Earth Fact Sheet (https://nssdc.gsfc.nasa.gov/planetary/factsheet/earthfact.html); UN WPP 2024, 8.2 billion baseline (https://population.un.org/wpp/); NIST CODATA proton radius (https://physics.nist.gov/cgi-bin/cuu/Value?rp); USGS earthquake magnitude, energy and shaking (https://www.usgs.gov/programs/earthquake-hazards/earthquake-magnitude-energy-release-and-shaking-intensity). Recoil and landing energy are elementary center-of-mass and mgh calculations under the stated assumptions.'
keywords=['what if everyone jumped at once','can humans move Earth','conservation of momentum explained','Earth recoil from human jump','simultaneous jump earthquake','crowd infrastructure logistics']
common=['#WhatIf','#Physics','#Earth','#Gravity','#Momentum','#ScienceExplained']
platforms={
 'youtube_shorts':dict(title='What if everyone on Earth jumped at once?',description='What if 8.2 billion people jumped at the same moment? Follow a cinematic Three.js thought experiment from a synchronized street jump to Earth\'s tiny recoil, a collective landing, and a city overwhelmed by humanity.\n\nEarth is about twelve trillion times more massive than all of us. A 30 cm jump gives an ideal peak recoil of about 2.5 × 10⁻¹⁴ m, much smaller than an atom. Internal jumping cannot boost the orbit of the Earth-human system. The larger problem is gathering everyone in one place—and getting them home.\n\n'+scope+'\n\n'+sources,tags=keywords+['everyone jumping at the same time','Earth human mass ratio','center of mass physics','jumping science short','human population thought experiment'],hashtags=common+['#WorldPopulation','#ScienceShorts'],keywords=keywords),
 'instagram_reels':dict(caption='What if everyone on Earth jumped at once?\nA tiny planetary recoil. A collective landing. Then a very human problem: water, roads, and care for billions in one place.\n\nThis 63-second 3D thought experiment uses an illustrative 8.2 billion people and a 30 cm jump. The recoil is far smaller than an atom; the system receives no orbital boost. Crowd-area diagrams exclude infrastructure and safe movement space. Ground vibration is illustrative, with no predicted earthquake magnitude.',hashtags=common+['#ScienceReels','#WorldPopulation'],keywords=keywords[:5]),
 'facebook_reels':dict(title='What if everyone on Earth jumped at once? The surprising real problem',description='Could a synchronized jump move our orbit or shake the whole world? This cinematic 3D explanation compares humanity with Earth, follows the tiny reversible recoil, and explores the supply problem of gathering billions in one city.\n\nThe model assumes 8.2 billion people, a 62 kg average body mass and a 30 cm jump. Body-area and seismic scenes are illustrative; tightly packing everyone would not provide safe jumping room.\n\n'+sources,hashtags=common+['#EarthScience'],keywords=keywords[:5]),
 'tiktok':dict(caption='What if 8.2 billion people jumped at once?\nEarth barely recoils. Getting everyone home is the bigger problem.\n\nWatch the street jump, momentum diagram, collective landing and city logistics twist. The model uses a 30 cm jump and an illustrative 2024 population baseline. Recoil is smaller than an atom—not a proton. Earthquake strength depends on unknown ground coupling.',hashtags=['#WhatIf','#PhysicsTok','#Earth','#Gravity','#Momentum','#ScienceTok','#WorldPopulation'],keywords=keywords[:5]),
 'x_video':dict(post='What if everyone on Earth jumped at once? Earth barely recoils; the system gets no orbital boost. Gathering billions creates a much bigger supply problem. A 63-second 3D thought experiment.',hashtags=['#WhatIf','#Physics','#Earth','#Gravity','#Momentum'],keywords=keywords[:4])}
meta=dict(schema_version='1.0.0',slug=slug,topic=story['project']['topic'],duration_s=63,video_file=f'output/{slug}.mp4',scientific_scope_note=scope,created_asset_ids=[a['proposed_id'] for a in story['asset_plan']['new_reusable_asset_candidates']],reused_asset_ids=[a['asset_id'] for a in story['asset_plan']['existing_assets_to_reuse']],published_urls={},platforms=platforms)
meta['production_details']=dict(narration_engine='Local Kokoro-82M v1.0 ONNX',male_voice='am_michael',narration_model_license='Apache-2.0',narration_model_source='https://huggingface.co/hexgrad/Kokoro-82M',caption_alignment='Local faster-whisper-small word timestamps aligned back to the exact script; real clip timing scaled with pitch-preserving tempo fits.',music_and_effects='Original deterministic synthesis using audio-synth-kit-v1; no sampled third-party music.',earth_texture_credit='NASA-derived Blue Marble and Black Marble texture set; see earth-textures-nasa-v1 registry rights and attribution.',visual_scope='17 animated Three.js shots across 9 scenes; representative human rigs and crowd blocks; labelled physical schematics.')
existing=ROOT/'metadata'/f'{slug}.json'
if existing.exists():
    prior=read(f'metadata/{slug}.json')
    for k in ['huggingface','published_urls','rendered_at_utc']:
        if k in prior:meta[k]=prior[k]
write(f'metadata/{slug}.json',meta)
print(f'Registered {len(meta["created_asset_ids"])} validated assets; recorded {len(meta["reused_asset_ids"])} reused IDs and five publishing platforms.')
print('X copy length:',len(platforms['x_video']['post']+'\n'+' '.join(platforms['x_video']['hashtags'])))
